contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_amount)); require(_amount <= 1000000000000000000000000000000);
        require(_amount <= address(this).balance);

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;

        c.Deposit{value: _amount}(); if (__ESBMC_reverted()) return;

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalAfter = address(c).balance;

        assert(balAfter == balBefore + _amount
            && contractBalAfter == contractBalBefore + _amount);
    }

    receive() external payable {}
}

