pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 _amount) internal {
        _amount = bound(_amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_amount <= address(this).balance);
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        try c.Deposit{value: _amount}() {} catch { return; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint contractBalAfter = address(c).balance;
        assertTrue(balAfter == balBefore + _amount
            && contractBalAfter == contractBalBefore + _amount);
    }

    function testFuzz_run(uint256 _amount) public {
        _run(_amount);
    }

    receive() external payable {}
}
